{
  "title": "A Cheaper Day in Bali",
  "summary": "We keep the rice terraces, then mix free stops and a low-priced warung so the day is gentler on the wallet while still feeling like Bali.",
  "stops": [
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The terraces stay, of course. The sun won’t wait, and neither should we.",
      "must_do_id": "m2"
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "A free slice of Ubud history, and it fits neatly before lunch.",
      "must_do_id": null
    },
    {
      "poi_id": "p15",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at a warung that keeps vegetarians happy and prices low. Terima kasih (thank you (Indonesian)) for that.",
      "must_do_id": null
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "A little market wander for local colour and photo spots, without the monkey business price tag.",
      "must_do_id": null
    },
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": null,
      "note": "Free beach time to stretch the afternoon and let the night owls ease into the evening.",
      "must_do_id": null
    },
    {
      "poi_id": "p15",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner back at the warung because it is cheap, cheerful, and everyone can eat well.",
      "must_do_id": null
    }
  ]
}
